/** Let the flywheel coast at the lowest priority, so that any other shooter command can interrupt it. */
public Command idle() {
  return run(coroutine -> coroutine.await(shooter.set(0)))
      .withPriority(Command.LOWEST_PRIORITY)
      .named("Shooter Idle");
}
